import {loadGuidedHistory,guidedWeaknesses,guidedResultScore} from './workshop-repair-guided-history.mjs';
import {caseInfo} from './workshop-content.mjs';
import {alternate} from './workshop-challenges.mjs';
export function mountGuidedHistory({language,available,hidden,launch}){
 const root=document.createElement('section');root.id='guidedRepairHistory';root.className='challenge-panel';document.querySelector('main').append(root);const t=(es,en)=>language()==='es'?es:en,local=x=>x[language()],name=g=>local(g.id==='primary'?caseInfo[g.kind].fix:alternate[g.kind].fix);
 function render(){root.replaceChildren();root.hidden=hidden();if(root.hidden)return;const add=(tag,text,host=root)=>{const n=document.createElement(tag);n.textContent=text;host.append(n);return n;};add('h2',t('Historial de decisiones guiadas','Guided repair history'));let rows=[];try{rows=loadGuidedHistory(localStorage);}catch{add('p',t('No se pudo leer el historial. Los datos guardados no se han modificado.','Could not read history. Saved data has not been modified.'));return;}add('p',t('Últimas 100 prácticas guiadas completadas, guardadas en este navegador. No alteran notas de examen, racha ni reparaciones verificadas. Los órdenes alternativos útiles cuentan como aciertos.','Latest 100 completed guided practices, saved in this browser. They do not change exam grades, streaks or verified repairs. Useful alternative orders count as correct choices.'));if(!rows.length){add('p',t('Completa una práctica guiada para descubrir qué intervenciones debes repasar.','Complete a guided practice to discover which interventions need review.'));return;}
 add('p',rows.length+t(' prácticas · primera nota ',' practices · first score ')+guidedResultScore(rows[0])+'/100 · '+t('última ','latest ')+guidedResultScore(rows.at(-1))+'/100');add('h3',t('Intervenciones con más errores','Interventions with the most mistakes'));add('p',t('Un error significa aplicar una corrección innecesaria o repetir una ya realizada. Se ordenan por número de errores; compara también el total de elecciones. El repaso conserva un caso donde ocurrió el error.','An error means applying an unnecessary correction or repeating one already made. Ranked by error count; also compare the number of choices. Reviews reuse a case in which the error occurred.'));
 for(const g of guidedWeaknesses(rows)){const card=add('article','');card.className='repair-progress-card';add('h4',name(g),card);add('p',g.wrong+'/'+g.total+t(' elecciones innecesarias · ',' unnecessary choices · ')+g.hints+t(' pistas usadas en estas decisiones',' hints used for these decisions'),card);const meter=add('meter','',card);meter.min=0;meter.max=g.total;meter.value=g.total-g.wrong;meter.setAttribute('aria-label',(g.total-g.wrong)+'/'+g.total+t(' útiles',' useful'));const b=add('button',g.wrong?t('Repasar esta dificultad','Review this difficulty'):t('Reforzar esta intervención','Reinforce this intervention'),card);b.dataset.guidedPractice=g.key;b.disabled=!available();b.onclick=()=>launch(g);}
 if(!available())add('p',t('Abre un examen completado para practicar en los bancos 3D.','Open a completed exam to practise in the 3D benches.'));const details=add('details','');add('summary',t('Ver resultados y decisiones','View results and decisions'),details);for(const g of [...rows].reverse()){const card=add('article','',details);add('h4',new Date(g.finished).toLocaleString(language(),{timeZone:'America/Bogota'})+' · '+local(caseInfo[g.user.kind].title)+' · '+guidedResultScore(g)+'/100',card);const list=add('ol','',card);for(const r of g.rounds)add('li',name({kind:g.user.kind,id:r.id})+' · '+(r.useful?t('Útil','Useful'):t('Innecesaria','Unnecessary'))+(r.hint?t(' · con pista',' · with hint'):''),list);}
 }
 return {render};
}
